//go:build windows

package clang

import (
	"testing"
)

// A command line as generated by CMake on Windows: the compiler is an absolute
// path using backslashes while the defines use \" to escape quotes.
const windowsCommand = `C:\Users\aminya\llvm\bin\clang++.exe ` +
	`-DCMAKE_INTDIR=\"Debug\" -IO:/GitHub/Project/include ` +
	`-c O:\GitHub\Project\src\main.cpp -o main.cpp.obj`

func TestSplitCommandStringKeepsBackslashPaths(t *testing.T) {
	words, err := splitCommandString(windowsCommand)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	expected := []string{
		`C:\Users\aminya\llvm\bin\clang++.exe`,
		`-DCMAKE_INTDIR="Debug"`,
		`-IO:/GitHub/Project/include`,
		`-c`,
		`O:\GitHub\Project\src\main.cpp`,
		`-o`,
		`main.cpp.obj`,
	}

	if len(words) != len(expected) {
		t.Fatalf("words = %q, want %q", words, expected)
	}
	for i := range expected {
		if words[i] != expected[i] {
			t.Errorf("words[%d] = %q, want %q", i, words[i], expected[i])
		}
	}
}

func TestParseClangCommandStringNormalizesWindowsCompiler(t *testing.T) {
	cmd, err := ParseClangCommandString(&DatabaseEntry{Command: windowsCommand})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if cmd.Compiler != "C:/Users/aminya/llvm/bin/clang++.exe" {
		t.Errorf("compiler = %q, want %q", cmd.Compiler, "C:/Users/aminya/llvm/bin/clang++.exe")
	}
	if cmd.InputPath != `O:\GitHub\Project\src\main.cpp` {
		t.Errorf("input path = %q, want %q", cmd.InputPath, `O:\GitHub\Project\src\main.cpp`)
	}
	if cmd.OutputPath != "main.cpp.obj" {
		t.Errorf("output path = %q, want %q", cmd.OutputPath, "main.cpp.obj")
	}
}
